"""Extract traced object silhouettes from the single overhead raster master.
All coordinates use the original 1536x1024 canvas. Visible RGB is never repainted.
"""
from pathlib import Path
from PIL import Image,ImageDraw
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
base=Image.open(ROOT/'public/assets/00_base_scene.png').convert('RGB')
assert base.size==(1536,1024)
contours={
'01_dove_olive':[(635,165),(640,165),(647,162),(651,158),(653,154),(656,152),(660,153),(662,157),(662,160),(665,163),(670,165),(673,167),(668,169),(660,169),(656,173),(649,175),(641,173),(635,171),(633,168)],
'02_scroll':[(698,431),(703,432),(714,436),(728,439),(740,444),(746,446),(748,451),(746,458),(742,464),(735,463),(723,460),(710,456),(697,451),(695,446),(696,437)],
'03_clay_jar':[(951,717),(952,711),(957,711),(960,705),(966,703),(973,704),(977,707),(982,707),(985,711),(985,718),(981,729),(980,737),(975,745),(965,751),(958,748),(953,742),(950,734),(950,724)],
'04_fish':[(1315,751),(1322,746),(1330,742),(1345,735),(1360,733),(1371,732),(1384,730),(1394,729),(1391,735),(1384,740),(1392,746),(1381,746),(1376,741),(1369,747),(1357,753),(1343,758),(1339,763),(1335,761),(1333,757),(1323,758),(1315,757)],
'05_grapes':[(210,639),(215,637),(219,644),(227,642),(231,645),(232,648),(237,648),(240,652),(238,657),(235,660),(238,664),(237,669),(234,671),(233,676),(229,678),(231,682),(229,686),(226,688),(226,693),(222,696),(218,694),(215,689),(211,689),(209,685),(211,679),(207,677),(207,673),(202,671),(202,667),(198,664),(200,659),(206,656),(206,651),(208,648),(207,644)],
'06_oil_lamp':[(828,471),(835,471),(842,474),(848,478),(848,484),(844,489),(838,492),(832,490),(826,486),(822,482),(822,478),(825,475)],
'07_bread':[(173,277),(176,273),(182,267),(189,263),(198,258),(207,255),(214,255),(218,258),(219,263),(216,269),(211,275),(202,281),(190,287),(181,290),(176,288),(173,284)],
'08_harp':[(582,731),(582,726),(586,722),(592,720),(599,723),(607,729),(616,735),(626,740),(631,737),(635,739),(637,744),(634,750),(619,803),(624,808),(623,814),(613,818),(600,823),(594,819),(592,812),(589,785),(585,751)],
'09_rainbow':[(1215,136),(1231,124),(1250,115),(1272,110),(1292,111),(1312,115),(1333,123),(1350,134),(1365,148),(1378,166),(1371,173),(1357,155),(1344,143),(1328,133),(1309,125),(1291,122),(1272,122),(1254,128),(1237,136),(1224,146)]
}
for name,points in contours.items():
 mask=Image.new('L',base.size);d=ImageDraw.Draw(mask);d.polygon(points,fill=255)
 if name=='01_dove_olive':
  rgb=np.array(base).astype(int);a=np.array(mask);r,g,b=rgb[:,:,0],rgb[:,:,1],rgb[:,:,2];yy,xx=np.indices(a.shape)
  leaves=(xx>=671)&(xx<=685)&(yy>=159)&(yy<=181)&(g>r*.85)&(g>b*1.4)&(g<160)&(r<150)
  a[leaves]=255;mask=Image.fromarray(a);d=ImageDraw.Draw(mask);d.line([(670,166),(677,172),(681,178)],fill=255,width=1)
 if name=='03_clay_jar':
  d.polygon([(978,711),(981,710),(982,714),(981,720),(978,725),(978,717)],fill=0)
  d.polygon([(953,715),(956,714),(956,718),(953,720)],fill=0)
 if name=='08_harp':
  d.polygon([(590,733),(597,730),(606,736),(616,742),(627,746),(616,789),(609,807),(600,776),(593,750)],fill=0)
  for p,q in [((592,734),(596,756)),((595,734),(599,769)),((598,735),(602,779)),((601,737),(604,790)),((604,738),(607,799)),((607,740),(609,801)),((610,741),(612,793)),((613,742),(615,781)),((616,744),(618,769)),((619,745),(621,759)),((622,746),(624,751))]:d.line([p,q],fill=255,width=1)
 rgba=np.array(base.convert('RGBA'));rgba[:,:,3]=np.array(mask);rgba[rgba[:,:,3]==0,:3]=0
 Image.fromarray(rgba).save(ROOT/f'public/assets/{name}.png',optimize=True)
print('Extracted nine overhead-scene RGBA layers without changing source pixels.')
